#include <stdlib.h>
#include <stdbool.h>

// Forward declaration of request_queue structure
struct request_queue {
    bool is_dying;
    int ref_count;
    void (*exit)(struct request_queue*, void*);
    void* flush_rq;
};

// Function to clean up flush request queue
int blk_init_allocated_queue(struct request_queue *q) {
    if (!q) {
        return -1; // Return error if queue is null
    }

    if (q->exit) {
        q->exit(q, q->flush_rq);
    }

    free(q->flush_rq);
    q->flush_rq = NULL;

    return -1; // Return memory allocation failure error code
}

// Function to check if the request queue is active
bool blk_get_queue(struct request_queue *q) {
    if (!q) {
        return false; // Return false if queue is null
    }

    if (!q->is_dying) {
        q->ref_count++;
        return true;
    }

    return false;
}
